/* ==========================================================================
   Antigravity Persian Chat - Stylesheet
   راست‌چین خودکار و فونت وزیرمتن برای چت و پرامپت در Antigravity IDE (نسخه ۲٫۶٫۰ و بالاتر)
   ========================================================================== */

/* اعلان فونت محلی وزیرمتن به صورت کاملاً آفلاین و سازگار با Content Security Policy */
@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-weight: 300;
  font-display: swap;
  src: local('Vazirmatn Light'), local('Vazirmatn-Light'),
       url('./fonts/vazirmatn-arabic.woff2') format('woff2'),
       url('./fonts/vazirmatn-latin.woff2') format('woff2'),
       url('https://fonts.gstatic.com/s/vazirmatn/v16/Dxxo8j6PP2D_kU2muijlGMWWMmk.woff2') format('woff2');
}

@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: local('Vazirmatn'), local('Vazirmatn Regular'), local('Vazirmatn-Regular'),
       local('Vazirmatn UI'), local('Vazirmatn-UI-Regular'), local('Vazirmatn-RD-UI-Regular'),
       url('./fonts/vazirmatn-arabic.woff2') format('woff2'),
       url('./fonts/vazirmatn-latin.woff2') format('woff2'),
       url('https://fonts.gstatic.com/s/vazirmatn/v16/Dxxo8j6PP2D_kU2muijlGMWWMmk.woff2') format('woff2');
}

@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: local('Vazirmatn Medium'), local('Vazirmatn-Medium'),
       local('Vazirmatn UI Medium'), local('Vazirmatn-UI-Medium'),
       url('./fonts/vazirmatn-arabic.woff2') format('woff2'),
       url('./fonts/vazirmatn-latin.woff2') format('woff2'),
       url('https://fonts.gstatic.com/s/vazirmatn/v16/Dxxo8j6PP2D_kU2muijlGMWWMmk.woff2') format('woff2');
}

@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: local('Vazirmatn Bold'), local('Vazirmatn-Bold'),
       local('Vazirmatn UI Bold'), local('Vazirmatn-UI-Bold'),
       url('./fonts/vazirmatn-arabic.woff2') format('woff2'),
       url('./fonts/vazirmatn-latin.woff2') format('woff2'),
       url('https://fonts.gstatic.com/s/vazirmatn/v16/Dxxo8j6PP2D_kU2muijlGMWWMmk.woff2') format('woff2');
}

/* متغیرهای پایه استایل */
:root {
  --ag-persian-font: 'Vazirmatn', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, system-ui, sans-serif;
  --ag-code-font: 'Fira Code', 'Cascadia Code', Consolas, 'Courier New', monospace;
  --ag-persian-line-height: 1.85;
}

/* اعمال فونت وزیرمتن بر روی پنل‌های چت، گام‌های گفتگو و پرامپت در Antigravity IDE 2.6.0+ */
.antigravity-agent-side-panel,
[data-testid="conversation-view"],
[data-testid="user-input-step"],
[data-testid="user-message-bubble"],
[data-quotable="true"],
[data-testid="agent-input-box"],
[data-testid="ask-question-writein"],
[data-testid="interaction-takeover-card"],
.agent-driven-pane,
.antigravity-agent-manager,
.animate-markdown,
.ag-persian-font {
  font-family: var(--ag-persian-font) !important;
}

/* اعمال فونت وزیرمتن به تگ‌های متنی درون پنل چت و گفتگو */
[data-testid="conversation-view"] p,
[data-testid="conversation-view"] li,
[data-testid="conversation-view"] h1,
[data-testid="conversation-view"] h2,
[data-testid="conversation-view"] h3,
[data-testid="conversation-view"] h4,
[data-testid="conversation-view"] h5,
[data-testid="conversation-view"] h6,
[data-testid="conversation-view"] blockquote,
[data-testid="conversation-view"] th,
[data-testid="conversation-view"] td,
.antigravity-agent-side-panel p,
.antigravity-agent-side-panel li,
.antigravity-agent-side-panel h1,
.antigravity-agent-side-panel h2,
.antigravity-agent-side-panel h3,
.antigravity-agent-side-panel h4,
.antigravity-agent-side-panel h5,
.antigravity-agent-side-panel h6,
.antigravity-agent-side-panel blockquote,
.antigravity-agent-side-panel th,
.antigravity-agent-side-panel td {
  font-family: var(--ag-persian-font) !important;
}

/* --------------------------------------------------------------------------
   استایل‌های راست‌چین (RTL) برای زبان فارسی
   -------------------------------------------------------------------------- */
.ag-persian-rtl,
[dir="rtl"] {
  direction: rtl !important;
  text-align: right !important;
  line-height: var(--ag-persian-line-height) !important;
  letter-spacing: 0 !important;
  unicode-bidi: plaintext !important;
}

/* استایل‌های چپ‌چین (LTR) برای متون انگلیسی در چت */
.ag-persian-ltr,
[dir="ltr"] {
  direction: ltr !important;
  text-align: left !important;
  line-height: 1.6 !important;
}

/* --------------------------------------------------------------------------
   پیام‌های کاربر در Antigravity 2.6.0 (User Input Step & Message Bubble)
   -------------------------------------------------------------------------- */
[data-testid="user-input-step"].ag-persian-rtl,
[data-testid="user-input-step"][dir="rtl"],
[data-testid="user-message-bubble"].ag-persian-rtl,
[data-testid="user-message-bubble"][dir="rtl"],
[data-quotable="true"].ag-persian-rtl,
[data-quotable="true"][dir="rtl"] {
  direction: rtl !important;
  text-align: right !important;
  line-height: var(--ag-persian-line-height) !important;
}

/* در Flexbox ردیف، وقتی حباب کاربر راست‌چین است */
[data-testid="user-input-step"].ag-persian-rtl [data-testid="user-message-bubble"],
[data-testid="user-input-step"][dir="rtl"] [data-testid="user-message-bubble"] {
  direction: rtl !important;
  text-align: right !important;
}

[data-testid="user-message-bubble"] [data-quotable="true"].ag-persian-rtl,
[data-testid="user-message-bubble"] [data-quotable="true"][dir="rtl"],
[data-testid="user-input-step"].ag-persian-rtl [data-quotable="true"] {
  direction: rtl !important;
  text-align: right !important;
  unicode-bidi: plaintext !important;
}

/* --------------------------------------------------------------------------
   جعبه ورودی پرامپت چت در Antigravity 2.6.0 (Lexical Editor & Textarea)
   -------------------------------------------------------------------------- */
[data-testid="agent-input-box"] [contenteditable="true"],
[data-testid="agent-input-box"] textarea,
[data-testid="conversation-view"] [contenteditable="true"],
[data-testid="conversation-view"] textarea,
div[contenteditable="true"].ag-persian-rtl,
div[contenteditable="true"][dir="rtl"] {
  font-family: var(--ag-persian-font) !important;
  line-height: 1.75 !important;
  transition: direction 0.15s ease, text-align 0.15s ease;
}

div[contenteditable="true"].ag-persian-rtl,
div[contenteditable="true"][dir="rtl"],
div[contenteditable="true"].ag-persian-rtl p,
div[contenteditable="true"][dir="rtl"] p,
div[contenteditable="true"].ag-persian-rtl span,
div[contenteditable="true"][dir="rtl"] span {
  direction: rtl !important;
  text-align: right !important;
}

/* راست‌چین کردن متن پیش‌فرض (Placeholder) هنگام فعال بودن RTL */
[data-testid="agent-input-box"] [contenteditable="true"][dir="rtl"] ~ p[class*="placeholder"],
[data-testid="agent-input-box"] [contenteditable="true"].ag-persian-rtl ~ p[class*="placeholder"],
[data-testid="agent-input-box"] p.pointer-events-none.ag-persian-rtl,
[data-testid="agent-input-box"] p.pointer-events-none[dir="rtl"] {
  direction: rtl !important;
  text-align: right !important;
  right: 0.5rem !important;
  left: auto !important;
}

/* --------------------------------------------------------------------------
   حفاظت از بلوک‌های کد (Code Blocks) - الزاما باید همیشه LTR بمانند
   -------------------------------------------------------------------------- */
.antigravity-agent-side-panel pre,
.antigravity-agent-side-panel pre code,
.antigravity-agent-side-panel .code-block,
.antigravity-agent-side-panel .monaco-editor,
[data-testid="conversation-view"] pre,
[data-testid="conversation-view"] pre code,
[data-testid="conversation-view"] .code-block,
[data-testid="conversation-view"] .monaco-editor,
.ag-persian-rtl pre,
.ag-persian-rtl pre code,
[dir="rtl"] pre,
[dir="rtl"] pre code {
  direction: ltr !important;
  text-align: left !important;
  font-family: var(--ag-code-font) !important;
  unicode-bidi: isolate !important;
  line-height: 1.5 !important;
  letter-spacing: normal !important;
}

/* --------------------------------------------------------------------------
   کدهای درون‌خطی (Inline Code) درون جملات فارسی
   -------------------------------------------------------------------------- */
.ag-persian-rtl code:not(pre code),
[dir="rtl"] code:not(pre code),
.antigravity-agent-side-panel .ag-persian-rtl code:not(pre code),
[data-testid="conversation-view"] .ag-persian-rtl code:not(pre code) {
  direction: ltr !important;
  unicode-bidi: isolate !important;
  display: inline !important;
  font-family: var(--ag-code-font) !important;
  font-size: 0.9em !important;
  padding: 0.15em 0.4em !important;
  margin: 0 0.25em !important;
  border-radius: 4px !important;
  background-color: var(--vscode-textCodeBlock-background, rgba(127, 127, 127, 0.15)) !important;
  color: var(--vscode-textPreformat-foreground, inherit) !important;
  vertical-align: baseline !important;
}

/* --------------------------------------------------------------------------
   اصلاح چیدمان لیست‌ها (Lists) در حالت راست‌چین
   -------------------------------------------------------------------------- */
ul.ag-persian-rtl,
ol.ag-persian-rtl,
.ag-persian-rtl ul,
.ag-persian-rtl ol,
[dir="rtl"] ul,
[dir="rtl"] ol {
  direction: rtl !important;
  text-align: right !important;
  padding-right: 1.7rem !important;
  padding-left: 0 !important;
  margin-right: 0 !important;
}

li.ag-persian-rtl,
.ag-persian-rtl li,
[dir="rtl"] li {
  direction: rtl !important;
  text-align: right !important;
  line-height: var(--ag-persian-line-height) !important;
  margin-bottom: 0.25rem !important;
}

/* --------------------------------------------------------------------------
   نقل‌قول‌ها (Blockquotes) در حالت فارسی
   -------------------------------------------------------------------------- */
blockquote.ag-persian-rtl,
.ag-persian-rtl blockquote,
[dir="rtl"] blockquote {
  direction: rtl !important;
  text-align: right !important;
  border-right: 3.5px solid var(--vscode-textBlockQuote-border, #007acc) !important;
  border-left: none !important;
  padding-right: 12px !important;
  padding-left: 0 !important;
  margin-right: 0 !important;
  margin-left: 0 !important;
  opacity: 0.95;
}

/* --------------------------------------------------------------------------
   عناوین (Headings) در حالت فارسی
   -------------------------------------------------------------------------- */
h1.ag-persian-rtl,
h2.ag-persian-rtl,
h3.ag-persian-rtl,
h4.ag-persian-rtl,
h5.ag-persian-rtl,
h6.ag-persian-rtl,
.ag-persian-rtl h1,
.ag-persian-rtl h2,
.ag-persian-rtl h3,
.ag-persian-rtl h4,
.ag-persian-rtl h5,
.ag-persian-rtl h6 {
  direction: rtl !important;
  text-align: right !important;
  font-family: var(--ag-persian-font) !important;
  font-weight: 700 !important;
  line-height: 1.6 !important;
}

/* --------------------------------------------------------------------------
   جدول‌ها (Markdown Tables) در حالت فارسی
   -------------------------------------------------------------------------- */
table.ag-persian-rtl,
.ag-persian-rtl table,
[dir="rtl"] table {
  direction: rtl !important;
  text-align: right !important;
  width: 100% !important;
}

table.ag-persian-rtl th,
table.ag-persian-rtl td,
.ag-persian-rtl th,
.ag-persian-rtl td,
[dir="rtl"] th,
[dir="rtl"] td {
  text-align: right !important;
  padding: 6px 12px !important;
}

file:cursor/styles.css.content:
/* ==========================================================================
   Cursor Persian Chat - Stylesheet
   راست‌چین خودکار و فونت وزیرمتن برای چت و Composer در نرم‌افزار Cursor
   ========================================================================== */

/* اعلان فونت محلی وزیرمتن به صورت کاملاً آفلاین و سازگار با Content Security Policy */
@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-weight: 300;
  font-display: swap;
  src: local('Vazirmatn Light'), local('Vazirmatn-Light'),
       url('./fonts/vazirmatn-arabic.woff2') format('woff2'),
       url('./fonts/vazirmatn-latin.woff2') format('woff2');
}

@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: local('Vazirmatn'), local('Vazirmatn Regular'), local('Vazirmatn-Regular'),
       local('Vazirmatn UI'), local('Vazirmatn-UI-Regular'), local('Vazirmatn-RD-UI-Regular'),
       url('./fonts/vazirmatn-arabic.woff2') format('woff2'),
       url('./fonts/vazirmatn-latin.woff2') format('woff2');
}

@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: local('Vazirmatn Medium'), local('Vazirmatn-Medium'),
       local('Vazirmatn UI Medium'), local('Vazirmatn-UI-Medium'),
       url('./fonts/vazirmatn-arabic.woff2') format('woff2'),
       url('./fonts/vazirmatn-latin.woff2') format('woff2');
}

@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: local('Vazirmatn Bold'), local('Vazirmatn-Bold'),
       local('Vazirmatn UI Bold'), local('Vazirmatn-UI-Bold'),
       url('./fonts/vazirmatn-arabic.woff2') format('woff2'),
       url('./fonts/vazirmatn-latin.woff2') format('woff2');
}

/* متغیرهای پایه استایل */
:root {
  --cursor-persian-font: 'Vazirmatn', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, system-ui, sans-serif;
  --cursor-code-font: 'Fira Code', 'Cascadia Code', Consolas, 'Courier New', monospace;
  --cursor-persian-line-height: 1.85;
}

/* اعمال فونت وزیرمتن به کانتینرهای پیام و چت در Cursor */
[data-react-transcript-root],
.composer-messages-container,
.composer-human-message,
.composer-human-message-content,
.composer-human-message-body,
.composer-message-markdown,
.composer-plan-markdown-container,
.agent-transcript-row-markdown,
.rendered-markdown,
.aislash-editor,
.aislash-editor-input,
.aislash-editor-input-readonly,
.composer-human-tiptap-readonly-editor,
.markdown-lexical-editor-container,
.markdown-lexical-editor-content-editable,
.markdown-lexical-editor-paragraph,
.bubble,
[data-bubble-id],
.cursor-persian-font {
  font-family: var(--cursor-persian-font) !important;
}

/* اعمال فونت بر روی تگ‌های متنی درون پیام‌ها */
.rendered-markdown p,
.rendered-markdown li,
.rendered-markdown h1,
.rendered-markdown h2,
.rendered-markdown h3,
.rendered-markdown h4,
.rendered-markdown h5,
.rendered-markdown h6,
.rendered-markdown blockquote,
.rendered-markdown th,
.rendered-markdown td,
.composer-messages-container p,
.composer-messages-container li,
.composer-messages-container h1,
.composer-messages-container h2,
.composer-messages-container h3,
.composer-human-message-content p,
.composer-human-message-content span,
.agent-transcript-row-markdown p,
.agent-transcript-row-markdown li {
  font-family: var(--cursor-persian-font) !important;
}

/* --------------------------------------------------------------------------
   استایل‌های راست‌چین (RTL) برای زبان فارسی
   -------------------------------------------------------------------------- */
.cursor-persian-rtl,
[data-cursor-dir="rtl"],
[dir="rtl"] {
  direction: rtl !important;
  text-align: right !important;
  line-height: var(--cursor-persian-line-height) !important;
  letter-spacing: 0 !important;
  unicode-bidi: plaintext !important;
}

/* اطمینان از عرض کامل و تراز به راست المان‌های بلوکی در Flexbox */
.rendered-markdown [dir="rtl"],
.composer-messages-container [dir="rtl"],
.composer-human-message-content [dir="rtl"],
.cursor-persian-rtl {
  width: 100% !important;
  box-sizing: border-box !important;
}

.cursor-persian-ltr,
[data-cursor-dir="ltr"],
[dir="ltr"] {
  direction: ltr !important;
  text-align: left !important;
}

/* تراز لیست‌ها در محیط راست‌چین */
.cursor-persian-rtl ul,
.cursor-persian-rtl ol,
[data-cursor-dir="rtl"] ul,
[data-cursor-dir="rtl"] ol,
[dir="rtl"] ul,
[dir="rtl"] ol {
  padding-right: 1.6rem !important;
  padding-left: 0 !important;
  margin-right: 0 !important;
  text-align: right !important;
  direction: rtl !important;
}

.cursor-persian-rtl li,
[data-cursor-dir="rtl"] li,
[dir="rtl"] li {
  text-align: right !important;
  direction: rtl !important;
}

/* نقل‌قول‌ها در زبان فارسی */
.cursor-persian-rtl blockquote,
[data-cursor-dir="rtl"] blockquote,
[dir="rtl"] blockquote {
  border-right: 3px solid var(--vscode-textBlockQuote-border, #4078f2) !important;
  border-left: none !important;
  padding-right: 0.8rem !important;
  padding-left: 0 !important;
  margin-right: 0 !important;
  text-align: right !important;
  direction: rtl !important;
}

/* تیترها در زبان فارسی */
.cursor-persian-rtl h1,
.cursor-persian-rtl h2,
.cursor-persian-rtl h3,
.cursor-persian-rtl h4,
.cursor-persian-rtl h5,
.cursor-persian-rtl h6,
[data-cursor-dir="rtl"] h1,
[data-cursor-dir="rtl"] h2,
[data-cursor-dir="rtl"] h3,
[data-cursor-dir="rtl"] h4,
[data-cursor-dir="rtl"] h5,
[data-cursor-dir="rtl"] h6,
[dir="rtl"] h1,
[dir="rtl"] h2,
[dir="rtl"] h3,
[dir="rtl"] h4,
[dir="rtl"] h5,
[dir="rtl"] h6 {
  font-weight: 700 !important;
  margin-top: 1.2rem !important;
  margin-bottom: 0.6rem !important;
  text-align: right !important;
  direction: rtl !important;
}

/* --------------------------------------------------------------------------
   حفاظت از کدهای برنامه‌نویسی (همواره چپ‌چین و با فونت مونو)
   -------------------------------------------------------------------------- */
pre,
code,
.monaco-editor,
.code-block,
.code-line,
.cursor-persian-rtl pre,
.cursor-persian-rtl code,
[data-cursor-dir="rtl"] pre,
[data-cursor-dir="rtl"] code,
[dir="rtl"] pre,
[dir="rtl"] code {
  direction: ltr !important;
  text-align: left !important;
  unicode-bidi: isolate !important;
}

pre,
.code-block {
  font-family: var(--cursor-code-font) !important;
  line-height: 1.5 !important;
}

/* کدهای درون‌خطی (Inline Code) میان متن‌های فارسی */
p code,
li code,
td code {
  font-family: var(--cursor-code-font) !important;
  direction: ltr !important;
  display: inline-block !important;
  padding: 0.15em 0.4em !important;
  margin: 0 0.2em !important;
  border-radius: 4px !important;
  background-color: var(--vscode-textCodeBlock-background, rgba(127, 127, 127, 0.12)) !important;
  vertical-align: baseline !important;
}

/* جدول‌ها در محتوای فارسی */
.cursor-persian-rtl table,
[data-cursor-dir="rtl"] table,
[dir="rtl"] table {
  direction: rtl !important;
  text-align: right !important;
  border-collapse: collapse !important;
  width: 100% !important;
}

.cursor-persian-rtl th,
.cursor-persian-rtl td,
[data-cursor-dir="rtl"] th,
[data-cursor-dir="rtl"] td,
[dir="rtl"] th,
[dir="rtl"] td {
  text-align: right !important;
  padding: 6px 12px !important;
}

/* کادرهای ورودی Composer و چت در Cursor */
.aislash-editor,
.aislash-editor-input,
.markdown-lexical-editor-container,
.markdown-lexical-editor-content-editable,
div[contenteditable="true"] {
  font-family: var(--cursor-persian-font) !important;
}

